import {useEffect, useState} from "react";
import {UserService} from "../../services/UserService";
import AddButton from "../../components/AddButton";
import CustomTable from "../../components/CustomTable";
import FormatDate from "../../utils/FormatDate";
import CustomModal from "../../components/CustomModal";
import {Modal} from "bootstrap";

export default function User() {
    const [users, setUsers] = useState([]);
    // const [error, setError] = useState("");
    // const [loading, setLoading] = useState(false);

    useEffect(() => {
        try {
            (async () => {
                const response = await UserService.get()
                setUsers(response)
            })();
        } catch (err) {
            console.log('Error while check cookie sign in: ', (err.response) ? err.response.data : err);
        }
    }, []);

    const headerTableSetting = [
        {header: "Username", accessor: "username"},
        {header: "Role", accessor: "role"},
        {header: "Created at", accessor: (u) => FormatDate(u.created_at)},
        {header: "Updated at", accessor: (u) => FormatDate(u.updated_at)}
    ]

    const fieldsSettingModal = [
        {label: "Username", name: "username", type: "text"},
        {
            label: "Role", name: "role", type: "select", options: [
                {label: "User", value: "USER"},
                {label: "Admin", value: "ADMIN"}
            ]
        }
    ];

