        modal.show();
    };

    const handleAddUser = (data) => {
        console.log("Dữ liệu submit:", data);
    };

    return (
        <>
            <div className={"container d-flex flex-column"}>
                <AddButton onClick={openModal}/>
                <CustomTable list={users} columns={headerTableSetting}/>
                <CustomModal id={'addUserModal'} title={"Add New User"} fields={fieldsSettingModal} onSubmit={handleAddUser}/>
            </div>
        </>
    )
}
